           "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(52, 197, 255, 0.22), transparent 34rem),
           linear-gradient(135deg, #080a10 0%, #11182a 55%, #080a10 100%);
       }

       #root,
       .page-shell {
         width: 100%;
       }

       .page-shell {
         display: grid;
         place-items: center;
       }

       .skip-link {
         position: fixed;
         top: 1rem;
         left: 1rem;
         z-index: 10;
         transform: translateY(-160%);
         border-radius: 999px;
         padding: 0.75rem 1rem;
         color: #071019;
         background: var(--ring);
         font-weight: 700;
         text-decoration: none;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid #071019;
         outline-offset: 3px;
       }

       .page-shell {
         width: 100%;
         min-height: 100vh;
         padding: clamp(1rem, 4vw, 3rem);
       }

       .card {
         width: min(100%, 30rem);
         border: 1px solid rgba(255, 255, 255, 0.12);
         border-radius: 1.5rem;
         padding: clamp(1.5rem, 5vw, 2.25rem);
         background:
           linear-gradient(180deg, rgba(255, 255, 255, 0.05), transparent),
           var(--panel);
         box-shadow: 0 1.5rem 4rem var(--shadow);
       }

       .eyebrow {
         margin: 0 0 0.75rem;
         color: var(--accent);
         font-size: 0.78rem;
         font-weight: 800;
         letter-spacing: 0.12em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 8vw, 3rem);
         line-height: 1;
         letter-spacing: -0.06em;
       }

       .intro {
         margin: 1rem 0 1.75rem;
         color: var(--muted);
         line-height: 1.6;
       }

       .form-field {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.25rem 0.85rem;
         align-items: start;
         border: 1px solid rgba(124, 219, 255, 0.22);
         border-radius: 1rem;
         padding: 1rem;
         background: var(--panel-strong);
       }

       .form-field input {
         width: 1.35rem;
         height: 1.35rem;
         margin: 0.15rem 0 0;
         accent-color: var(--accent-strong);
         cursor: pointer;
       }

       .form-field label {
         color: var(--text);
         font-weight: 750;
         line-height: 1.4;
         cursor: pointer;
       }

       .required {
         color: var(--accent);
         font-weight: 900;
       }

       .helper,
       .error {
         grid-column: 2;
         margin: 0;
         font-size: 0.95rem;
         line-height: 1.45;
       }

       .helper {
         color: var(--muted);
       }

       .error {
         color: var(--danger);
         font-weight: 700;
       }

       .error[hidden] {
         display: none;
       }

       .actions {
         margin-top: 1.25rem;
       }

       button {
         width: 100%;
         min-height: 3rem;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.25rem;
         color: #061018;
         background: linear-gradient(135deg, var(--accent), var(--accent-strong));
         font: inherit;
         font-weight: 850;
         cursor: pointer;
         box-shadow: 0 0.75rem 1.5rem rgba(52, 197, 255, 0.2);
       }

       button:hover {
         filter: brightness(1.08);
       }

       button:active {
         transform: translateY(1px);
       }

       :focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 4px;
       }

       .status {
         min-height: 1.5rem;
         margin: 1rem 0 0;
         color: var(--accent);
         font-weight: 700;
       }

       @media (max-width: 24rem) {
         .form-field {
           grid-template-columns: 1fr;
         }

         .helper,
         .error {
           grid-column: 1;
         }
       }

       @media (forced-colors: active) {
         body,
         .card,
         .form-field {
           color: CanvasText;
           background: Canvas;
           border-color: CanvasText;
         }

         .helper,
         .intro {
           color: CanvasText;
         }

         .error {
           color: Mark;
         }

         button,
         .skip-link {
           color: ButtonText;
           background: ButtonFace;
           border: 2px solid ButtonText;
         }

         :focus-visible {
           outline-color: Highlight;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>

     <script>
       const CheckboxField = () => `
         <div class="form-field">
           <input
             id="terms-consent"
             name="termsConsent"
             type="checkbox"
             required
             aria-describedby="terms-helper terms-error"
           >
           <label for="terms-consent">
             I agree to the terms of use <span class="required" aria-hidden="true">*</span>
           </label>
           <p class="helper" id="terms-helper">You must accept to continue.</p>
           <p class="error" id="terms-error" hidden>Error: Agree to the terms of use before continuing.</p>
         </div>
       `;

       const ConsentForm = () => `
         <form id="consent-form" novalidate>
           ${CheckboxField()}
           <div class="actions">
             <button type="submit">Agree and continue</button>
           </div>
           <p class="status" id="form-status" aria-live="polite"></p>
         </form>
       `;

       const App = () => `
         <main class="page-shell" id="main-content">
           <section class="card" aria-labelledby="form-title">
             <p class="eyebrow">Consent required</p>
             <h1 id="form-title">Review terms</h1>
             <p class="intro">Confirm that you accept the terms of use to continue.</p>
             ${ConsentForm()}
           </section>
         </main>
       `;

       document.querySelector("#root").innerHTML = App();

       const form = document.querySelector("#consent-form");
       const checkbox = document.querySelector("#terms-consent");
       const error = document.querySelector("#terms-error");
       const status = document.querySelector("#form-status");

       const setValidityState = () => {
         const isValid = checkbox.checked;
         checkbox.setAttribute("aria-invalid", String(!isValid));
         error.hidden = isValid;
         if (isValid) {
           status.textContent = "";
         }
         return isValid;
       };

       checkbox.addEventListener("change", setValidityState);

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!setValidityState()) {
           status.textContent = "";
           checkbox.focus();
           return;
         }

         status.textContent = "Thanks. Your consent has been recorded.";
       });
     </script>
   </body>
 </html>

